27	message InstanceSetting {
28	  InstanceSettingKey key = 1;
29	  oneof value {
30	    InstanceBasicSetting basic_setting = 2;
31	    InstanceGeneralSetting general_setting = 3;
32	    InstanceStorageSetting storage_setting = 4;
33	    InstanceMemoRelatedSetting memo_related_setting = 5;
34	    InstanceTagsSetting tags_setting = 6;
35	    InstanceNotificationSetting notification_setting = 7;
36	    InstanceAISetting ai_setting = 8;
37	  }
38	}
