152	  }
153	}
154	
155	message InstanceAISetting {
156	  // providers is the list of AI provider configurations available instance-wide.
157	  repeated AIProviderConfig providers = 1;
158	
159	  // transcription is the speech-to-text feature configuration.
160	  // When unset or transcription.provider_id is empty, transcription is disabled.
161	  TranscriptionConfig transcription = 2;
162	}
163	
164	message AIProviderConfig {
165	  string id = 1;
166	  string title = 2;
167	  AIProviderType type = 3;
168	  string endpoint = 4;
169	  // api_key is write-only at the API layer and is required by the server to call providers.
170	  string api_key = 5;
171	}
172	
173	enum AIProviderType {
174	  AI_PROVIDER_TYPE_UNSPECIFIED = 0;
175	  OPENAI = 1;
176	  GEMINI = 2;
177	}
178	
179	// TranscriptionConfig configures the speech-to-text feature.
180	message TranscriptionConfig {
181	  // provider_id references an entry in InstanceAISetting.providers[].id.
182	  // Empty string means transcription is disabled.
183	  string provider_id = 1;
184	
185	  // model is the provider-specific model identifier.
186	  // Empty string falls back to the engine default.
187	  // OPENAI examples:
188	  //   - whisper-1 (legacy, lower cost)
189	  //   - gpt-4o-transcribe, gpt-4o-mini-transcribe (higher quality)
190	  //   - gpt-4o-transcribe-diarize (includes speaker labels)
191	  // GEMINI examples:
192	  //   - gemini-2.5-flash (default, multimodal call)
193	  //   - gemini-2.5-pro
194	  string model = 2;
195	
196	  // language is the default ISO 639-1 language hint sent to the provider.
197	  // Empty string lets the provider auto-detect.
198	  string language = 3;
199	
200	  // prompt is a default spelling/vocabulary hint passed to the provider.
201	  // Used as the OpenAI Whisper "prompt" parameter (a soft hint that the model
202	  // may ignore) and folded into the Gemini generation prompt as a "Context and
203	  // spelling hints" block (which the LLM will treat more literally).
204	  string prompt = 4;
205	}
